const cwd = "/Users/aleph/Projects/blogger-go";
const results = await parallel([
  () => tool.bash({ command: "ls -la", cwd }).then(r => ({k:"lsla", v:r.text})),
  () => tool.bash({ command: "find . -path ./.git -prune -o -print | head -300", cwd }).then(r => ({k:"tree", v:r.text})),
  () => tool.bash({ command: "test -f go.mod && cat go.mod || echo 'NO_GO_MOD'", cwd }).then(r => ({k:"gomod", v:r.text})),
  () => tool.bash({ command: "go list ./... 2>&1 | head -100; echo '---'; go version", cwd }).then(r => ({k:"gopkgs", v:r.text})),
  () => tool.bash({ command: "find . -path ./.git -prune -o -type f \\( -iname '*.md' -o -iname 'README*' -o -iname 'DESIGN*' -o -iname '*.txt' -o -iname 'LICENSE*' \\) -print", cwd }).then(r => ({k:"docs", v:r.text})),
  () => tool.bash({ command: "git remote -v; echo '---LOG---'; git log --oneline -15 2>&1; echo '---BRANCH---'; git branch -a 2>&1; echo '---STATUS---'; git status --short 2>&1 | head -50", cwd }).then(r => ({k:"git", v:r.text})),
  () => tool.bash({ command: "find . -name '*.go' -not -path './.git/*' | head -200; echo '---COUNT---'; find . -name '*.go' -not -path './.git/*' | wc -l", cwd }).then(r => ({k:"gofiles", v:r.text})),
]);
for (const r of results) {
  console.log("===== " + r.k + " =====");
  console.log(r.v);
}

